You are a formal verification assistant. The following Dafny program fails Dafny verification.

=== PROGRAM ===
// Dafny verification of binary search alogirthm from binary_search.py
// Inspired by: https://ece.uwaterloo.ca/~agurfink/stqam/rise4fun-Dafny/#h211

method BinarySearch(arr: array<int>, target: int) returns (index: int)
    requires distinct(arr)
    requires sorted(arr)
    ensures -1 <= index < arr.Length
    ensures index == -1 ==> not_found(arr, target) && index >= 0
    ensures index != -1 ==> found(arr, target, index)
{
    var low, high := 0 , arr.Length-1;
    while low <= high
        invariant 0 <= low <= high + 1
        invariant low-1 <= high < arr.Length
        invariant forall i :: 0 <= i <= low && high <= i < arr.Length ==> arr[i] != target
    { 
        var mid := (low + high) / 2;
        if arr[mid] == target
        {
           return mid;
        }
        else if arr[mid] < target
        {
           low := mid + 1;
        }
        else
        {
           high := mid - 1;
        }
    }

    return -1;
}

// Predicate to check that the array is sorted
predicate sorted(a: array<int>)
reads a
{
   forall j, k :: 0 <= j < k < a.Length ==> a[j] <= a[k] 
}

// Predicate to that each element is unique
predicate distinct(arr: array<int>)
    reads arr
{
    forall i, j :: 0 <= i < arr.Length && 0 <= j < arr.Length ==> arr[i] != arr[j]
}

// Predicate to that the target is not in the array
predicate not_found(arr: array<int>, target: int)
reads arr
{
    (forall j :: 0 <= j < arr.Length ==> arr[j] != target)
}

// Predicate to that the target is in the array
predicate found(arr: array<int>, target: int, index: int)
requires -1 <= index < arr.Length;
reads arr
{
    if index == -1 then false
    else if arr[index] == target then true
    else false
}

=== DAFNY ERROR ===
program.dfy(32,4): Error: a postcondition could not be proved on this return path

program.dfy(8,60): Related location: this is the postcondition that could not be proved
  |
8 |     ensures index == -1 ==> not_found(arr, target) && index >= 0
  |                                                             ^^

Dafny program verifier finished with 5 verified, 1 error

=== COUNTEREXAMPLE ===
At initial state: arr.Length = 1, target = 7719. At a program state: high = 0, low = 0.

Analyze the failure and respond with ONLY a valid JSON object — no explanation, no markdown, no code fences. Use exactly this structure:

{
  "spec_element": "<one of: requires | invariant | ensures>",
  "proof_obligation": "<one of: initiation | preservation | bridge>",
  "diagnosis": "<explanation of what broke and why>",
  "repair": "<the corrected Dafny specification line that restores the intended behavior>"
}

Definitions:
- requires: the precondition that must hold before the method executes
- invariant: the loop invariant that must hold throughout the loop
- ensures: the postcondition that the method must guarantee on return
- initiation: the precondition does not establish the invariant at loop entry
- preservation: the loop body does not maintain the invariant
- bridge: the invariant and loop exit condition do not imply the postcondition

